function clean(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '');
}

function safeJsonParse(value, fallback = {}) {
  if (!value) return fallback;

  if (typeof value === 'object') return value;

  try {
    return JSON.parse(value);
  } catch (error) {
    return fallback;
  }
}

function toBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;
  if (String(value).toLowerCase() === 'true') return true;
  return false;
}

function firstName(nombre) {
  return String(nombre || 'candidato').split(' ')[0];
}

function isGreeting(text) {
  return (
    text === 'hola' ||
    text === 'buenos dias' ||
    text === 'buenas tardes' ||
    text === 'buenas noches' ||
    text === 'hey' ||
    text === 'hello'
  );
}

function isYes(text) {
  return (
    text.includes('si') ||
    text.includes('comenzar') ||
    text.includes('continuar') ||
    text.includes('me interesa') ||
    text === '1'
  );
}

function isNo(text) {
  return (
    text.includes('no') ||
    text.includes('no gracias') ||
    text.includes('no por ahora') ||
    text.includes('despues') ||
    text.includes('despu├®s')
